UPDATE hr_offer
SET status = 'ACCEPTED', accepted_at = NOW()
WHERE id = #{id} AND status = #{fromStatus}

UPDATE hr_offer
SET status = 'REJECTED', rejected_at = NOW(), reject_reason = #{rejectReason}
WHERE id = #{id} AND status = #{fromStatus}

UPDATE hr_offer
SET status = 'EXPIRED'
WHERE id = #{id} AND status = #{fromStatus}

UPDATE hr_offer
SET status = 'WITHDRAWN'
WHERE id = #{id} AND status = #{fromStatus}

UPDATE hr_offer
SET last_sync_time = NOW()
WHERE id = #{id}

